pub fn help(code: Code) -> Option<String> {
    Some(match code {
        Code::ManifestNotFound => {
            "create a `qxide.toml` in the project directory, or run from inside a project".into()
        }
        Code::NotInstalled => "run `qxide install` to download dependencies".into(),
        Code::LockOutdated => "run `qxide install` to update `qxide.lock`".into(),
        Code::PackageNotFound => {
            "check the spelling, or search the registry with `qxide search <query>`".into()
        }
        Code::ChecksumMismatch => {
            "do not use this package; report it to the registry maintainers".into()
        }
        Code::RegistryUnavailable => {
            "check your network connection, or pass `--offline` to use the local cache".into()
        }
        Code::VersionConflict => "relax one of the version requirements in `qxide.toml`".into(),
        Code::LanguageVersion => {
            "update `qxide`, or choose a package version that supports this version".into()
        }
        Code::Offline => "run once without `--offline` to populate the cache".into(),
        _ => return None,
    })
}

pub fn usage_commands() -> &'static str {
    "  add <PKG>[@VER] [--path DIR]       Add a dependency to qxide.toml and install it
  remove <PKG>                       Remove a dependency
  install [--locked] [--offline]     Download and verify packages in qxide.lock
  publish [--dry-run]                Package the project and submit it to the registry
  search <WORD>                      Search the package registry
"
}
